mapper.select:
SELECT ROW_NUMBER() OVER(ORDER BY a.usr_id) AS rownum, -- 순번 a.usr_id AS userId, -- 사용자ID a.usr_nm AS userNm, -- 사용자명 a.ognz_cd AS deptCd, -- 소속부서코드 b.ognz_nm AS deptNm, -- 소속부서명 a.auth_cd AS userGradeCd, -- 사용자등급코드 d.auth_nm AS userGradeNm, -- 사용자등급명 a.lgn_yn AS lgnYn, -- 로그인여부 a.lgn_ip AS lgnIp, -- 로그인IP c.cmmn_cd_nm AS wrkStatNm, -- 근태코드명 s.wrk_stat_cd AS wrkStatCd, -- 근태코드 TO_CHAR(a.entr_dt, 'YYYYMMDD') AS jncmpYmd, -- 입사일자 TO_CHAR(a.rtir_dt, 'YYYYMMDD') AS rsgntnYmd, -- 퇴사일자 CASE WHEN a.entr_dt IS NOT NULL THEN TO_CHAR(a.entr_dt, 'YYYY-MM-DD') ELSE NULL END AS useStartYmd, -- 사용시작일 CASE WHEN a.rtir_dt IS NOT NULL THEN TO_CHAR(a.rtir_dt, 'YYYY-MM-DD') ELSE NULL END AS useEndYmd -- 사용종료일 FROM cdm_own.usr a LEFT JOIN cdm_own.ognz b ON a.ognz_cd = b.ognz_cd LEFT JOIN cdm_own.sup_wrk_stat s ON s.user_id = a.usr_id AND a.ognz_cd = s.ognz_cd AND s.crtr_ymd = TO_CHAR(CURRENT_DATE, 'YYYYMMDD') LEFT JOIN cdm_own.cmmn_cd c ON c.cd_grop_cd = 'WRK_STAT_CD' AND c.cmmn_cd = s.wrk_stat_cd AND c.lcal_cd = 'ko' LEFT JOIN cdm_own.auth d ON a.auth_cd = d.auth_cd WHERE 1=1
AND a.ognz_cd = #{ognzCd}
AND a.auth_cd = #{userGradeCd}
AND a.usr_id LIKE '%' || #{userId} || '%'
AND a.usr_nm LIKE '%' || #{userNm} || '%'
AND a.use_yn = #{useYn}
ORDER BY a.sys_reg_dttm desc, a.usr_id

SELECT COUNT(*)
FROM cdm_own.usr
WHERE usr_id = #{userId}
